INSERT INTO posts (title,content,author,phone,product,password_hash,is_secret,reply,replied_at,created_at) VALUES
('지점 2곳 인터넷 동시 개통 문의','휴게실과 회의실에 IPTV를 설치하려고 합니다. 총 2대 예정입니다. 설치 비용과 월 이용료, 셋탑 임대료 포함 금액으로 안내 부탁드립니다.','신민지','01014538401','KT 기업용 인터넷','seed',1,'안녕하세요, KT 공식가입센터입니다.  문의 감사합니다. 요청하신 회선 수 기준으로 견적을 정리해 안내드리겠습니다. 방문 상담도 가능하니 편하신 시간대를 회신해 주시면 담당자가 방문 일정을 잡아드립니다.  감사합니다.','2026-11-05 09:49:00','2026-11-05 09:49:00'),
('IPTV 셋탑박스 임대료 문의','안녕하세요. 현재 사용 중인 회선 약정이 만료되어 KT로 이동을 검토하고 있습니다. 설치 희망 지역은 서울 구로구 인근 사무실이며, 사용 인원은 4명 정도입니다. 가능한 요금제와 설치 소요 기간, 사무실 랜공사 비용도 함께 안내 부탁드립니다.','김소영','01030766619','KT IPTV','seed',1,'안녕하세요, KT 공식가입센터입니다.  문의주신 내용 확인했습니다. 해당 지역은 기가 회선 설치가 가능하며, 사무실 규모에 맞춘 결합 상품을 추천드립니다. 설치까지는 신청 후 영업일 기준 3~5일 소요되며, 기업전화 결합 시 구내공사는 무료로 지원됩니다.  상세 견적은 남겨주신 연락처로 안내드리겠습니다. 감사합니다.','2026-11-05 11:12:00','2026-11-05 11:12:00'),
('공장용 전용회선 설치 가능 여부 문의','안녕하세요. 현재 사용 중인 회선 약정이 만료되어 KT로 이동을 검토하고 있습니다. 설치 희망 지역은 서울 구로구 인근 사무실이며, 사용 인원은 12명 정도입니다. 가능한 요금제와 설치 소요 기간, 사무실 랜공사 비용도 함께 안내 부탁드립니다.','신은지','01023100772','GIGA office (전용회선)','seed',1,'안녕하세요, KT 공식가입센터입니다.  문의주신 내용 확인했습니다. 해당 지역은 기가 회선 설치가 가능하며, 사무실 규모에 맞춘 결합 상품을 추천드립니다. 설치까지는 신청 후 영업일 기준 3~5일 소요되며, 기업전화 결합 시 구내공사는 무료로 지원됩니다.  상세 견적은 남겨주신 연락처로 안내드리겠습니다. 감사합니다.','2026-11-05 09:35:00','2026-11-05 09:35:00'),
('기업전화 6회선 신규 개통 문의','지점을 새로 열게 되어 인터넷과 전화를 함께 신청하려 합니다. 개통까지 걸리는 기간과 설치 가능 요일을 알려주시면 감사하겠습니다.','최나래','01063049403','KT 기업인터넷 전화','seed',1,NULL,NULL,'2026-11-05 11:25:00'),
